-- Phase 7B ONE-TIME DATA CLEANUP; not a migration. Prepared only; never executed by Codex.
-- Use one complete static file per manual gate. No JSON/CSV baseline transfer.
-- Requires PASS Gate 1 pins before execution. Use a quiet maintenance window.
-- Any error/mismatch rolls cleanup back. Never run a fragment or remove a guard.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='120s';
SET LOCAL idle_in_transaction_session_timeout='120s';
SET LOCAL row_security=off;
