,'true'),('finance_payable_entitlement_sources','true'),('finance_payable_entitlements','true'),('finance_payee_audit','true'),('finance_payee_destinations','true'),('finance_payees','true'),('finance_payment_allocation_reallocations','true'),('finance_payment_audit_events','true'),('finance_payment_evidence','true'),('finance_payment_invoice_allocations','true'),('finance_payment_money_allocation_audit','true'),('finance_payment_money_allocations','true'),('finance_payment_wht_components','true'),('finance_payments','true'),('finance_payout_allocations','true'),('finance_payout_audit','true'),('finance_payouts','true'),('finance_quotation_items','true'),('finance_quotation_payment_installment_items','true'),('finance_quotation_payment_installments','true'),('finance_quotation_payment_terms','true'),('finance_quotations','true'),('finance_receipt_audit_events','true'),('finance_receipt_invoice_allocations','true'),('finance_receipts','true'),('finance_tax_correction_audit_events','true'),('finance_tax_correction_documents','true'),('finance_tax_correction_lines','true'),('finance_tax_document_corrections','true'),('finance_tax_filing_allocations','true'),('finance_tax_filing_audit','true'),('finance_tax_filings','true'),('finance_tax_invoice_audit_events','true'),('finance_tax_invoice_items','true'),('finance_tax_invoice_source_coverages','true'),('finance_tax_invoices','true'),('finance_tax_periods','true'),('finance_tax_point_events','true'),('finance_tax_position_audit','true'),('finance_tax_position_facts','true'),('finance_tax_remittance_audit','true'),('finance_tax_remittances','true'),('finance_tax_source_revisions','true'),('finance_treasury_transfer_legs','true'),('finance_treasury_transfers','true'),('finance_vp_revenue_distribution_audit','true'),('finance_vp_revenue_distributions','true'),('case_audit_logs','coalesce(r.table_name = ANY(ARRAY[''finance_account_opening_balance_audit_events'',''finance_account_opening_balances'',''finance_billable_charge_au